import functools
import time

# ---------- 基础装饰器：计算函数执行时间 ----------
def timer_decorator(func):
    """打印函数执行时间（秒）"""
    @functools.wraps(func)  # 保留原函数元数据
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result
    return wrapper

@timer_decorator
def slow_function(n):
    """模拟耗时操作"""
    time.sleep(0.1)
    return sum(range(n))

# ---------- 带参数的装饰器 ----------
def retry_decorator(max_retries=3, delay=1.0):
    """失败时重试，支持自定义重试次数和延迟"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    print(f"Attempt {attempt+1} failed: {e}")
                    time.sleep(delay)
            raise RuntimeError(f"{func.__name__} failed after {max_retries} attempts")
        return wrapper
    return decorator

@retry_decorator(max_retries=3, delay=0.5)
def unstable_service(x):
    """模拟不稳定的外部服务"""
    import random
    if random.random() < 0.7:
        raise ConnectionError("Service unavailable")
    return x * 2

# ---------- 类装饰器：统计函数调用次数 ----------
class CountCalls:
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        print(f"Call {self.calls} of {self.func.__name__}")
        return self.func(*args, **kwargs)

@CountCalls
def greet(name):
    return f"Hello, {name}!"

# 运行测试
if __name__ == "__main__":
    print("--- Timer decorator ---")
    print(slow_function(10000))
    print("\n--- Retry decorator ---")
    print(unstable_service(10))
    print("\n--- Class decorator ---")
    print(greet("Alice"))
    print(greet("Bob"))

